import { check, revise, FILES, LABELS } from './checker.mjs';
const $=id=>document.getElementById(id);
const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
let fixture,candidate,generation=0;
const presets={original:[400000,550000],changed:[400000,500000],balanced:[450000,600000]};
const names={depositsInTransitCents:'Deposits in transit',outstandingPaymentsCents:'Outstanding payments',adjustedStatementCents:'Adjusted statement balance',differenceCents:'Difference',withinTolerance:'Within tolerance'};
function cents(id){const value=$(id).value;if(!/^\d+(?:\.\d{1,2})?$/.test(value))throw Error('Enter a nonnegative amount with at most two decimal places.');const n=Math.round(Number(value)*100);if(!Number.isSafeInteger(n)||n>1e12)throw Error('Amount is too large for this example.');return n;}
function showFiles(){if(!candidate)return;const file=$('file').value;const display=text=>file.endsWith('.json')?JSON.stringify(JSON.parse(text),null,2):text;$('before').textContent=display(fixture.original[file]);$('after').textContent=display(candidate[file]);}
function changed(){generation++;$('result').className='result pending';$('result-title').textContent='Changes not checked yet';$('result-message').textContent='Run the check to compare these files with the retained reference.';$('checks').replaceChildren();$('changes').replaceChildren();try{candidate=revise(fixture.original,cents('deposits'),cents('payments'));const calc=JSON.parse(candidate['calculation.json']);$('difference').textContent=money(calc.differenceCents);$('balance').textContent=calc.withinTolerance?'Balances':'Unexplained difference';$('verify').disabled=false;showFiles();}catch(e){candidate=null;$('difference').textContent='—';$('balance').textContent='Enter valid amounts';$('verify').disabled=true;$('result-title').textContent='Check the amounts';$('result-message').textContent=e.message;$('after').textContent='Invalid candidate amounts.';}}
function selectCase(name){if(!Object.hasOwn(presets,name))throw Error('Unknown example');const [d,p]=presets[name];$('deposits').value=(d/100).toFixed(2);$('payments').value=(p/100).toFixed(2);document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===name)));changed();}
function line(label,value){const row=document.createElement('div');row.className='checkline';const a=document.createElement('span'),b=document.createElement('strong');a.textContent=label;b.textContent=value;row.append(a,b);$('checks').append(row);}
async function runCheck(){if(!candidate)throw Error('Enter valid amounts first.');const revision=generation,snapshot=structuredClone(candidate);$('verify').disabled=true;$('result-title').textContent='Checking file fingerprints…';const result=await check(snapshot,fixture.manifestWire,fixture.anchor,fixture.original);if(revision!==generation)return {status:'SUPERSEDED'};$('verify').disabled=false;$('result').className='result '+(result.ok?'pass':'fail');$('result-title').textContent=result.ok?'Matches retained package':'Verification failed';$('result-message').textContent=result.invalid?'The package could not be checked.':result.ok?'All seven file fingerprints match. The calculation and simulated approval reference also check out.':result.calculation.withinTolerance?'It still balances. But these are not the files associated with the retained package and its simulated approval.':'The supporting files changed. The recalculated amount also leaves an unexplained difference.';$('checks').replaceChildren();$('changes').replaceChildren();if(result.invalid)return result;line('Retained commitment',result.commitmentMatches&&result.contextMatches?'Matches saved reference':'Does not match');line('Package files',result.ok?'7 of 7 match':`${7-result.changes.length} of 7 match`);line('Calculation arithmetic',result.arithmeticMatches?'Checks out':'Does not check out');line('Earlier simulated approval',result.approvalMatches?'Refers to this package':'Refers to different files');for(const change of result.changes){const box=document.createElement('div');box.className='change';const title=document.createElement('strong');title.textContent=change.label+' changed';box.append(title);for(const d of result.differences.filter(d=>d.file===change.file)){const p=document.createElement('p');const format=v=>d.field.endsWith('Cents')?money(v):String(v);p.textContent=`${names[d.field]||d.field}: ${format(d.before)} → ${format(d.after)}`;box.append(p);}const detail=document.createElement('details'),summary=document.createElement('summary'),old=document.createElement('code'),now=document.createElement('code');summary.textContent='See file fingerprints';old.textContent='Retained: '+change.retainedHash;now.textContent='Current: '+change.candidateHash;detail.append(summary,old,now);box.append(detail);$('changes').append(box);}return result;}
$('form').addEventListener('submit',e=>{e.preventDefault();runCheck().catch(()=>{$('result-title').textContent='Unable to check this package';$('verify').disabled=false;});});
for(const id of ['deposits','payments'])$(id).addEventListener('input',()=>{document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed','false'));changed();});
document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>selectCase(b.dataset.case)));
$('file').addEventListener('change',showFiles);
document.querySelectorAll('input,[data-case]').forEach(el=>el.disabled=true);
try{const response=await fetch('./fixture.json');if(!response.ok)throw Error('Fixture unavailable');fixture=await response.json();for(const file of FILES){const option=document.createElement('option');option.value=file;option.textContent=LABELS[file];$('file').append(option);} $('file').value='reconciling-items.json';$('anchor').textContent=fixture.anchor.expectedCommitment;selectCase('original');document.querySelectorAll('input,[data-case]').forEach(el=>el.disabled=false);await runCheck();}catch{$('result-title').textContent='The example could not load';$('result-message').textContent='Reload the page to try again.';$('verify').disabled=true;}
export {selectCase,runCheck};
// Optional agent entry point uses exactly the visible preset and check actions.
const context=document.modelContext;
if(fixture&&context?.registerTool){
  const lifetime=new AbortController();
  addEventListener('pagehide',()=>lifetime.abort(),{once:true});
  try{Promise.resolve(context.registerTool({name:'check_reconciliation_example',title:'Check reconciliation example',description:'Select a synthetic example, update the visible amounts and check its files against the retained package.',inputSchema:{type:'object',properties:{example:{type:'string',enum:['original','changed','balanced']}},required:['example'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||Object.keys(input).length!==1||!Object.hasOwn(presets,input.example))throw Error('Choose original, changed or balanced.');selectCase(input.example);const r=await runCheck();return {status:r.status,differenceCents:r.calculation?.differenceCents,changedFiles:r.changes?.map(c=>c.file)};}},{signal:lifetime.signal})).catch(()=>{});}catch{}
}
